const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const withTimeout = (p, ms) => {
  let t;
  const timer = new Promise((_, rej) => { t = setTimeout(() => rej(new Error('timeout')), ms); });
  return Promise.race([p, timer]).finally(() => clearTimeout(t));
};
async function retry(fn, tries = 3, base = 5) {
  for (let i = 0; ; i++) {
    try { return await fn(i); } catch (e) { if (i >= tries - 1) throw e; await sleep(base * 2 ** i); }
  }
}
async function pool(items, limit, fn) {
  const out = []; let next = 0, active = 0, peak = 0;
  await Promise.all(Array.from({ length: limit }, async () => {
    while (next < items.length) {
      const i = next++; active++; peak = Math.max(peak, active);
      out[i] = await fn(items[i]); active--;
    }
  }));
  return { out, peak };
}
const safeParse = (s, fallback = null) => { try { return JSON.parse(s); } catch { return fallback; } };
(async () => {
  console.log(await withTimeout(sleep(5).then(() => 'fast'), 50));
  console.log(await withTimeout(sleep(100), 10).catch(e => e.message));
  console.log(await retry(async (i) => { if (i < 2) throw new Error('fail' + i); return 'ok after ' + i; }));
  console.log(await pool([1, 2, 3, 4, 5], 2, async (n) => { await sleep(5); return n * n; }));
  console.log(safeParse('{bad'), safeParse('{"a":1}'), safeParse('x', 'dflt'));
})();

