const $ = (s, r = document) => r.querySelector(s);
const list = $('#list');
let n = 0;
const addItem = () => {
  n++;
  const li = Object.assign(document.createElement('li'), { innerHTML: `Task ${n} <span class="x" data-del>x</span>` });
  li.dataset.id = n;
  list.append(li);
};
addItem(); addItem();
$('#add').addEventListener('click', addItem);
list.addEventListener('click', (e) => {
  const del = e.target.closest('[data-del]');
  const li = e.target.closest('li');
  if (!li || !list.contains(li)) return;
  if (del) { li.remove(); $('#out').textContent = 'Deleted ' + li.dataset.id; return; }
  li.classList.toggle('done');
  $('#out').textContent = 'Toggled ' + li.dataset.id;
});

